mapper.select:
SELECT 
  FROM pay10_month
 INNER JOIN emp01_person ON pay10_person_id = emp01_person_id
 INNER JOIN emp02_others ON pay10_person_id = emp02_person_id
 INNER JOIN emp03_trans  ON pay10_person_id = emp03_person_id
 WHERE (emp03_person_id, emp03_trans_date) IN (
        SELECT emp03_person_id, MAX(emp03_trans_date)
          FROM emp01_person
         INNER JOIN emp03_trans ON emp03_person_id = emp01_person_id
         WHERE emp01_company_id = #{companyId}
           AND emp03_trans_date <= #{payDate}
         GROUP BY emp03_person_id
 )
   AND pay10_company_id = #{companyId}
   AND pay10_date       = #{payDate}
   AND pay10_pay_cd     = #{payCode}
 ORDER BY emp01_emp_no

SELECT (to_char(pay10_date,'yyyy-mm-dd')||' / '||f_cdnm('PayMonthCode', pay10_pay_cd, pay10_company_id, f_sysdate())) AS pay_group_nm, pay10_company_id AS company_id, pay10_date AS date, pay10_pay_cd AS pay_cd FROM pay10_month WHERE to_char(pay10_date, 'yyyy') = #{year} AND pay10_company_id = #{companyId} AND pay10_pay_cd like #{payCode}
AND pay10_pay_cd IN ('01', '02')
GROUP BY pay10_company_id, pay10_date, pay10_pay_cd ORDER BY pay10_company_id, pay10_date DESC, pay10_pay_cd

SELECT count(*)
  FROM pay05_relate_appr
 INNER JOIN apr01_appr b ON pay05_appr_id = apr01_appr_id
 WHERE pay05_company_id = #{companyId}
   AND pay05_pay_cd     = #{payCode}
   AND pay05_start_date = #{payDate}

   AND pay05_retire_id  = #{monthId}

   AND apr01_status_cd in ('10','20','30')

SELECT count(*)
  FROM act02_journal
 WHERE act02_company_id   = #{companyId}
   AND act02_date         = #{payDate}
   AND act02_pay_month_cd = #{payCode}

   AND act02_retire_id    = #{monthId}

