mapper.update:
UPDATE pay10_month
   SET pay10_work_day          = #{req.workDay},
       pay10_total_work_time   = #{totalWorkTime},
       pay10_extend_work_time  = #{req.extendWorkTime},
       pay10_night_work_time   = #{req.nightWorkTime},
       pay10_holiday_work_time = #{req.holidayWorkTime}
 WHERE pay10_month_id   = #{monthId}
   AND pay10_company_id = #{companyId}

