SELECT count(*)
  FROM sys12_calendar
 WHERE sys12_working_yn not in ('false')
   AND to_char(sys12_day,'yyyymm') = #{payDateInt}
   AND sys12_day >= #{hireDate}

   AND sys12_day <= #{retireDate}

   AND sys12_company_id = 1

SELECT count(*)
  FROM pay10_month
 WHERE pay10_company_id = #{companyId}
   AND pay10_person_id  = #{personId}
   AND pay10_date       = #{payDate}
   AND pay10_pay_cd     = #{payCode}

mapper.insert:
INSERT INTO pay11_month_item
SELECT f_create_seq(),
       #{monthId},
       pay11_item_type,
       pay11_item_cd,
       pay11_item_amt
  FROM pay11_month_item
       INNER JOIN pay10_month ON pay10_month_id = pay11_month_id
 WHERE pay10_company_id = #{companyId}
   AND pay10_person_id  = #{personId}
   AND pay11_item_cd NOT IN ('221','231','241')
   AND pay10_date = (
        SELECT MAX(pay10_date)
          FROM pay10_month
         WHERE pay10_pay_cd    = #{payCode}
           AND pay10_person_id = #{personId}
           AND CAST(TO_CHAR(pay10_date,'yyyymm') AS numeric) <= CAST(#{payDateInt} AS numeric) - 1
   )
   AND pay10_pay_cd = #{payCode}
